// === seasonal/themes/newyear.js ===
// New Year Theme - Новогоднее оформление
// Период: 20 декабря - 15 января

(function () {
    'use strict';

    const NewYearTheme = {
        id: 'newyear',
        name: 'Новый год',
        icon: '🎄',

        // Модальное окно
        modalTitle: 'С Новым годом! 🎄',
        modalContent: 'Пусть этот год принесёт новые возможности, интересные проекты и яркие достижения! Желаю кода без багов и деплоя без проблем!',

        // Диапазон дат
        dateRange: {

            start: '12-20',
            end: '01-15'
        },

        // CSS переменные для переопределения
        cssVars: {
            '--accent': '#fbbf24', // золотой
            '--accent-secondary': '#3b82f6', // синий
            '--bg-primary': 'rgba(15, 23, 42, 0.8)',
            '--bg-secondary': 'rgba(30, 41, 59, 0.6)',
            '--text-highlight': '#fbbf24',
            '--border-color': 'rgba(251, 191, 36, 0.3)'
        },

        // Canvas для снежинок
        canvas: null,
        ctx: null,
        animationId: null,
        snowflakes: [],

        // Конфигурация снежинок
        config: {
            snowflakeCount: 100,
            minSize: 2,
            maxSize: 6,
            minSpeed: 0.5,
            maxSpeed: 2,
            wind: 0.5
        },

        /**
         * Инициализация темы
         */
        init: function () {
            this.createCanvas();
            this.createGarland();
            this.createBanner();
            this.startSnowfall();
        },

        /**
         * Создаёт canvas для снежинок
         */
        createCanvas: function () {
            this.canvas = document.createElement('canvas');
            this.canvas.className = 'seasonal-canvas newyear-canvas';
            this.canvas.id = 'newyear-snow';
            this.ctx = this.canvas.getContext('2d');

            this.resizeCanvas();
            document.body.appendChild(this.canvas);

            // Обработчик изменения размера
            window.addEventListener('resize', () => this.resizeCanvas(), { passive: true });
        },

        /**
         * Изменяет размер canvas
         */
        resizeCanvas: function () {
            this.canvas.width = window.innerWidth;
            this.canvas.height = window.innerHeight;
        },

        /**
         * Создаёт гирлянду
         */
        createGarland: function () {
            const garland = document.createElement('div');
            garland.className = 'seasonal-garland newyear-garland';
            garland.id = 'newyear-garland';

            // Добавляем мигающие огни
            const colors = ['#ef4444', '#3b82f6', '#22c55e', '#fbbf24', '#ec4899', '#8b5cf6'];
            for (let i = 0; i < 20; i++) {
                const light = document.createElement('div');
                light.className = 'seasonal-light';
                light.style.left = `${5 + i * 5}%`;
                light.style.top = '15px';
                light.style.backgroundColor = colors[i % colors.length];
                light.style.animationDelay = `${i * 0.1}s`;
                garland.appendChild(light);
            }

            document.body.appendChild(garland);
        },

        /**
         * Создаёт баннер
         */
        createBanner: function () {
            const banner = document.createElement('div');
            banner.className = 'seasonal-banner newyear-banner';
            banner.id = 'newyear-banner';
            banner.innerHTML = '🎄 С Новым годом! 🎅';
            banner.style.background = 'linear-gradient(135deg, rgba(251, 191, 36, 0.2), rgba(59, 130, 246, 0.2))';
            banner.style.border = '1px solid rgba(251, 191, 36, 0.3)';
            banner.style.color = '#fbbf24';

            document.body.appendChild(banner);
        },

        /**
         * Инициализирует снежинки
         */
        initSnowflakes: function () {
            this.snowflakes = [];
            for (let i = 0; i < this.config.snowflakeCount; i++) {
                this.snowflakes.push({
                    x: Math.random() * this.canvas.width,
                    y: Math.random() * this.canvas.height,
                    size: this.config.minSize + Math.random() * (this.config.maxSize - this.config.minSize),
                    speed: this.config.minSpeed + Math.random() * (this.config.maxSpeed - this.config.minSpeed),
                    opacity: 0.3 + Math.random() * 0.7,
                    sway: Math.random() * Math.PI * 2
                });
            }
        },

        /**
         * Запускает анимацию снегопада
         */
        startSnowfall: function () {
            this.initSnowflakes();

            const animate = () => {
                this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);

                this.snowflakes.forEach(flake => {
                    // Обновление позиции
                    flake.y += flake.speed;
                    flake.sway += 0.02;
                    flake.x += Math.sin(flake.sway) * 0.5 + this.config.wind;

                    // Сброс позиции если ушла за экран
                    if (flake.y > this.canvas.height) {
                        flake.y = -10;
                        flake.x = Math.random() * this.canvas.width;
                    }
                    if (flake.x > this.canvas.width) {
                        flake.x = 0;
                    } else if (flake.x < 0) {
                        flake.x = this.canvas.width;
                    }

                    // Рисуем снежинку
                    this.ctx.beginPath();
                    this.ctx.arc(flake.x, flake.y, flake.size, 0, Math.PI * 2);
                    this.ctx.fillStyle = `rgba(255, 255, 255, ${flake.opacity})`;
                    this.ctx.fill();

                    // Добавляем блик
                    this.ctx.beginPath();
                    this.ctx.arc(flake.x - flake.size * 0.3, flake.y - flake.size * 0.3, flake.size * 0.2, 0, Math.PI * 2);
                    this.ctx.fillStyle = `rgba(255, 255, 255, ${flake.opacity * 0.8})`;
                    this.ctx.fill();
                });

                this.animationId = requestAnimationFrame(animate);
            };

            animate();
        },

        /**
         * Уничтожает тему
         */
        destroy: function () {
            // Останавливаем анимацию
            if (this.animationId) {
                cancelAnimationFrame(this.animationId);
                this.animationId = null;
            }

            // Удаляем canvas
            if (this.canvas && this.canvas.parentNode) {
                this.canvas.parentNode.removeChild(this.canvas);
                this.canvas = null;
                this.ctx = null;
            }

            // Удаляем гирлянду
            const garland = document.getElementById('newyear-garland');
            if (garland && garland.parentNode) {
                garland.parentNode.removeChild(garland);
            }

            // Удаляем баннер
            const banner = document.getElementById('newyear-banner');
            if (banner && banner.parentNode) {
                banner.parentNode.removeChild(banner);
            }

            // Удаляем обработчик resize
            window.removeEventListener('resize', () => this.resizeCanvas());

            this.snowflakes = [];
        }
    };

    // Регистрируем тему
    if (window.SeasonalManager) {
        window.SeasonalManager.registerTheme(NewYearTheme);
    } else {
        // Если менеджер ещё не загружен, ждём
        window.addEventListener('DOMContentLoaded', () => {
            if (window.SeasonalManager) {
                window.SeasonalManager.registerTheme(NewYearTheme);
            }
        });
    }
})();


// === seasonal/themes/programmer-day.js ===
// Programmer's Day Theme - День программиста (256-й день года)
// Дата: 13 сентября (12 в високосный год)

(function () {
    'use strict';

    const ProgrammerDayTheme = {
        id: 'programmer',
        name: 'День программиста',
        icon: '💻',

        // Модальное окно
        modalTitle: 'С Днём программиста! 💻',
        modalContent: '256-й день года — праздник всех, кто превращает кофе в код и идеи в реальность. Пусть ваши команды всегда выполняются без ошибок!',

        // Плавающая дата - 256-й день года
        checkDate: function (date, year) {

            if (!window.SeasonalDateUtils) return false;
            const programmerDay = window.SeasonalDateUtils.getProgrammerDayDate(year);
            const checkDate = new Date(date.getFullYear(), date.getMonth(), date.getDate());
            return checkDate.getTime() === programmerDay.getTime();
        },

        // CSS переменные - терминальный стиль
        cssVars: {
            '--accent': '#22c55e', // зелёный терминала
            '--accent-secondary': '#16a34a',
            '--bg-primary': 'rgba(0, 20, 0, 0.9)',
            '--bg-secondary': 'rgba(0, 40, 0, 0.7)',
            '--text-highlight': '#4ade80',
            '--border-color': 'rgba(34, 197, 94, 0.3)',
            '--text-primary': '#86efac',
            '--text-secondary': '#4ade80'
        },

        // Canvas для падающего кода
        canvas: null,
        ctx: null,
        animationId: null,
        codeDrops: [],

        config: {
            dropCount: 50,
            chars: '01アイウエオカキクケコサシスセソタチツテトナニヌネノハヒフヘホマミムメモヤユヨラリルレロワヲン',
            fontSize: 14,
            minSpeed: 1,
            maxSpeed: 3
        },

        /**
         * Инициализация темы
         */
        init: function () {
            this.createCanvas();
            this.createBanner();
            this.createTerminalEffect();
            this.startCodeRain();
        },

        /**
         * Создаёт canvas
         */
        createCanvas: function () {
            this.canvas = document.createElement('canvas');
            this.canvas.className = 'seasonal-canvas programmer-canvas';
            this.canvas.id = 'programmer-code-rain';
            this.ctx = this.canvas.getContext('2d');

            this.resizeCanvas();
            document.body.appendChild(this.canvas);

            window.addEventListener('resize', () => this.resizeCanvas(), { passive: true });
        },

        /**
         * Изменяет размер canvas
         */
        resizeCanvas: function () {
            this.canvas.width = window.innerWidth;
            this.canvas.height = window.innerHeight;
        },

        /**
         * Создаёт баннер
         */
        createBanner: function () {
            const banner = document.createElement('div');
            banner.className = 'seasonal-banner programmer-banner';
            banner.id = 'programmer-banner';
            banner.innerHTML = '💻 С Днём программиста! 0x100';
            banner.style.background = 'linear-gradient(135deg, rgba(34, 197, 94, 0.2), rgba(0, 0, 0, 0.4))';
            banner.style.border = '1px solid rgba(34, 197, 94, 0.4)';
            banner.style.color = '#22c55e';
            banner.style.fontFamily = 'monospace';

            document.body.appendChild(banner);
        },

        /**
         * Создаёт эффект терминала
         */
        createTerminalEffect: function () {
            // Добавляем scanlines
            const scanlines = document.createElement('div');
            scanlines.id = 'programmer-scanlines';
            scanlines.style.cssText = `
                position: fixed;
                top: 0;
                left: 0;
                width: 100%;
                height: 100%;
                pointer-events: none;
                z-index: 2;
                background: repeating-linear-gradient(
                    0deg,
                    rgba(0, 0, 0, 0.1),
                    rgba(0, 0, 0, 0.1) 1px,
                    transparent 1px,
                    transparent 2px
                );
                opacity: 0.3;
            `;
            document.body.appendChild(scanlines);
        },

        /**
         * Инициализирует падающий код
         */
        initCodeDrops: function () {
            this.codeDrops = [];
            const columns = Math.floor(this.canvas.width / this.config.fontSize);

            for (let i = 0; i < this.config.dropCount; i++) {
                this.codeDrops.push({
                    x: Math.floor(Math.random() * columns) * this.config.fontSize,
                    y: Math.random() * -100,
                    speed: this.config.minSpeed + Math.random() * (this.config.maxSpeed - this.config.minSpeed),
                    chars: [],
                    brightness: 0.5 + Math.random() * 0.5
                });

                // Заполняем начальные символы
                const dropLength = 5 + Math.floor(Math.random() * 15);
                for (let j = 0; j < dropLength; j++) {
                    this.codeDrops[i].chars.push(
                        this.config.chars[Math.floor(Math.random() * this.config.chars.length)]
                    );
                }
            }
        },

        /**
         * Запускает анимацию падающего кода
         */
        startCodeRain: function () {
            this.initCodeDrops();
            this.ctx.font = `${this.config.fontSize}px monospace`;

            const animate = () => {
                // Полупрозрачный чёрный для эффекта следа
                this.ctx.fillStyle = 'rgba(0, 0, 0, 0.05)';
                this.ctx.fillRect(0, 0, this.canvas.width, this.canvas.height);

                this.codeDrops.forEach(drop => {
                    // Обновляем символы
                    for (let i = 0; i < drop.chars.length; i++) {
                        const char = drop.chars[i];
                        const y = drop.y - i * this.config.fontSize;

                        // Первый символ - яркий, остальные - тусклые
                        if (i === 0) {
                            this.ctx.fillStyle = `rgba(134, 239, 172, ${drop.brightness})`;
                            this.ctx.shadowBlur = 10;
                            this.ctx.shadowColor = '#22c55e';
                        } else {
                            const alpha = (1 - i / drop.chars.length) * 0.5;
                            this.ctx.fillStyle = `rgba(34, 197, 94, ${alpha})`;
                            this.ctx.shadowBlur = 0;
                        }

                        this.ctx.fillText(char, drop.x, y);
                    }

                    // Сбрасываем shadow
                    this.ctx.shadowBlur = 0;

                    // Обновляем позицию
                    drop.y += drop.speed;

                    // Обновляем символы
                    if (Math.random() > 0.95) {
                        drop.chars.pop();
                        drop.chars.unshift(
                            this.config.chars[Math.floor(Math.random() * this.config.chars.length)]
                        );
                    }

                    // Сброс позиции
                    if (drop.y - drop.chars.length * this.config.fontSize > this.canvas.height) {
                        drop.y = 0;
                        drop.x = Math.floor(Math.random() * (this.canvas.width / this.config.fontSize)) * this.config.fontSize;
                    }
                });

                this.animationId = requestAnimationFrame(animate);
            };

            animate();
        },

        /**
         * Уничтожает тему
         */
        destroy: function () {
            if (this.animationId) {
                cancelAnimationFrame(this.animationId);
                this.animationId = null;
            }

            if (this.canvas && this.canvas.parentNode) {
                this.canvas.parentNode.removeChild(this.canvas);
                this.canvas = null;
                this.ctx = null;
            }

            const banner = document.getElementById('programmer-banner');
            if (banner && banner.parentNode) {
                banner.parentNode.removeChild(banner);
            }

            const scanlines = document.getElementById('programmer-scanlines');
            if (scanlines && scanlines.parentNode) {
                scanlines.parentNode.removeChild(scanlines);
            }

            window.removeEventListener('resize', () => this.resizeCanvas());

            this.codeDrops = [];
        }
    };

    // Регистрируем тему
    if (window.SeasonalManager) {
        window.SeasonalManager.registerTheme(ProgrammerDayTheme);
    } else {
        window.addEventListener('DOMContentLoaded', () => {
            if (window.SeasonalManager) {
                window.SeasonalManager.registerTheme(ProgrammerDayTheme);
            }
        });
    }
})();


